 function create(seed,map){map=Number(map);if(!C.integer(map,0,2))map=0;return{version:1,rng:seed>>>0,map:map,phase:'build',wave:0,core:20,credits:100,capacitors:2,towers:Array(6).fill(null),selected:0,enemies:[],queue:[],clock:0,nextId:1,kills:0,mods:[],offers:[],paused:true,speed:1,message:'选择炮位后建造。建议先部署两座脉冲塔，再迎接第一波。',recorded:false};}
